use rs_lvgl_ui::prelude::*;

fn view(theme: &Theme) -> View<()> {
    column([
        label("Hello, LVGL").style(Style::title(theme)),
        label("A screen is a tree of ordinary Rust values.").style(Style::body(theme)),
        button("Start building").style(Style::accent(theme)),
    ])
    .style(Style::screen(theme).pad(24).gap(16))
}

use rs_lvgl_ui::prelude::*;

fn view(theme: &Theme) -> View<()> {
    let actions = row([
        button("Back").style(Style::body(theme)),
        label("Step 2 of 3").style(Style::body(theme).flex_grow(1)),
        button("Continue").style(Style::accent(theme)),
    ])
    .style(Style::surface(theme).width(Size::Percent(100)).gap(12));

    column([
        label("Make room").style(Style::title(theme)),
        label("The middle label grows into the available space."),
        actions,
    ])
    .style(Style::screen(theme).pad(24).gap(20))
}

use rs_lvgl_ui::prelude::*;

fn view(theme: &Theme) -> View<()> {
    let tiles = grid(
        [GridTrack::Fr(1), GridTrack::Fr(1)],
        [GridTrack::Px(72), GridTrack::Px(72)],
        [
            button("Top left").grid_cell(0, 0, 1, 1),
            button("Top right").grid_cell(1, 0, 1, 1),
            button("Two columns").grid_cell(0, 1, 2, 1),
        ],
    )
    .style(Style::surface(theme).width(Size::Percent(100)).gap(12));

    column([
        label("A place for everything").style(Style::title(theme)),
        tiles,
    ])
    .style(Style::screen(theme).pad(24).gap(20))
}

use rs_lvgl_ui::prelude::*;

fn page_title<M>(text: &str, theme: &Theme) -> View<M> {
    column([
        label("WORKSPACE").style(Style::muted(theme)),
        label(text).style(Style::title(theme)),
    ])
    .style(Style::default().gap(8))
}

fn view(theme: &Theme) -> View<()> {
    let content = label("Notification preferences");
    let title = page_title("Settings", theme);

    column([title, content, button("Save").style(Style::accent(theme))])
        .style(Style::screen(theme).pad(24).gap(24))
}

use rs_lvgl_ui::prelude::*;

fn view(theme: &Theme) -> View<()> {
    column([
        label("Device settings").style(Style::title(theme)),
        row([
            label("Brightness").style(Style::body(theme)),
            slider(0, 100, 64).style(Style::default().width(Size::Px(240)).height(Size::Px(16))),
            label("64%"),
        ])
        .style(Style::surface(theme).gap(24)),
        row([label("Notifications"), switch(true)]).style(Style::surface(theme).gap(24)),
        button("Apply settings").style(Style::accent(theme)),
    ])
    .style(Style::screen(theme).pad(24).gap(24))
}

use rs_lvgl_ui::prelude::*;

fn view(theme: &Theme) -> View<()> {
    let devices = [(41, "Studio"), (73, "Kitchen"), (92, "Bedroom")];
    let rows = devices.into_iter().map(|(id, name)| {
        row([
            label(name).style(Style::body(theme).flex_grow(1)),
            label(format!("ID {id}")).style(Style::muted(theme)),
        ])
        .key(Key::Id(id))
        .style(Style::surface(theme).width(Size::Percent(100)).pad(16))
    });

    column([label("Your devices").style(Style::title(theme))])
        .children(rows)
        .style(Style::screen(theme).pad(24).gap(12))
}
